403	func TestChangesCompactPollAndSubscription(t *testing.T) {
404		h, _ := newTestHandler(t)
405		registerDevice(t, h, "dev-1")
406		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
407		if w.Code != http.StatusOK {
408			t.Fatal(w.Body.String())
409		}
410		postDocChanges(t, h, "doc", "dev-1", 3)
411		w, _ = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": nil})
412		if w.Code != http.StatusOK {
413			t.Fatal(w.Body.String())
414		}
415	
416		// A long poll parked at the tail is not woken by the compaction: it
417		// returns only when its own wait deadline expires.
418		type pollResult struct {
419			body    map[string]any
420			elapsed time.Duration
421		}
422		pollDone := make(chan pollResult, 1)
423		go func() {
424			start := time.Now()
425			_, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes/poll?after=3&waitMs=300")
426			pollDone <- pollResult{body, time.Since(start)}
427		}()
428		time.Sleep(50 * time.Millisecond)
429		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK {
430			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
431		}
432		select {
433		case got := <-pollDone:
434			if got.body["timedOut"] != true {
435				t.Fatalf("poll timedOut = %v", got.body)
436			}
437			if next := int64(got.body["nextCursor"].(float64)); next != 3 {
438				t.Fatalf("poll nextCursor = %d, want 3", next)
439			}
440			if got.elapsed < 200*time.Millisecond {
441				t.Fatalf("poll returned after %v: the compaction woke it", got.elapsed)
442			}
443		case <-time.After(3 * time.Second):
444			t.Fatal("poll did not return")
445		}
446	
447		// A fully trimmed document is still known: a poll inside the trimmed
448		// range parks, times out and reports the boundary as the next cursor.
449		postDocChanges(t, h, "full", "dev-1", 2)
450		w, _ = postJSON(t, h, "/v1/documents/full/snapshots", map[string]any{"cursor": 2, "state": nil})
451		if w.Code != http.StatusOK {
452			t.Fatal(w.Body.String())
453		}
454		if w := compactChanges(t, h, "full", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":2}\n" {
455			t.Fatalf("full compact = %d %q", w.Code, w.Body.String())
456		}
457		_, body := doRequest(t, h, http.MethodGet, "/v1/documents/full/changes/poll?after=1&waitMs=50")
458		if body["timedOut"] != true {
459			t.Fatalf("full poll timedOut = %v", body)
460		}
461		if next := int64(body["nextCursor"].(float64)); next != 2 {
462			t.Fatalf("full poll nextCursor = %d, want the boundary 2", next)
463		}
464		if changes := body["changes"].([]any); len(changes) != 0 {
465			t.Fatalf("full poll changes = %v", changes)
466		}
467	
468		// A subscription starting inside the trimmed range backfills from the
469		// first online change after the boundary, then continues live.
470		srv := httptest.NewServer(h)
471		defer srv.Close()
472		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
473		if conn == nil {
474			t.Fatalf("subscribe status = %d", resp.StatusCode)
475		}
476		defer conn.close()
477		if c := conn.readChange(); c.ID != "c3" || c.Cursor != 3 {
478			t.Fatalf("backfill frame = %+v, want c3 at cursor 3", c)
479		}
480		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
481			"deviceId": "dev-1",
482			"changes":  []any{map[string]any{"id": "c4", "payload": map[string]any{"n": 4}}},
483		})
484		if w.Code != http.StatusOK {
485			t.Fatal(w.Body.String())
486		}
487		if c := conn.readChange(); c.ID != "c4" || c.Cursor != 4 {
488			t.Fatalf("live frame = %+v, want c4 at cursor 4", c)
489		}
490	}
