557	// After a full trim the snapshot cursor judgment follows the never-reset
558	// cursor space: creating a snapshot for a trimmed cursor still succeeds, a
559	// repeat reports created=false, and a restore of that snapshot keeps its
560	// idempotency — all unchanged across a restart.
561	func TestSnapshotAfterFullTrimHTTP(t *testing.T) {
562		dbPath := filepath.Join(t.TempDir(), "sync.db")
563		open := func(t *testing.T) (http.Handler, *app.App) {
564			t.Helper()
565			s, err := app.Open(dbPath)
566			if err != nil {
567				t.Fatal(err)
568			}
569			return NewHandler(s), s
570		}
571	
572		h, s := open(t)
573		registerDevice(t, h, "dev-1")
574		postDocChanges(t, h, "doc", "dev-1", 2)
575		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": nil})
576		if w.Code != http.StatusOK {
577			t.Fatal(w.Body.String())
578		}
579		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":2}\n" {
580			t.Fatalf("full compact = %d %q", w.Code, w.Body.String())
581		}
582	
583		// A trimmed cursor is still an existing cursor: the snapshot is created;
584		// the identical repeat is idempotent.
585		snapshotAtOne := func(h http.Handler) {
586			t.Helper()
587			w, body := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
588			if w.Code != http.StatusOK || body["created"] != true {
589				t.Fatalf("snapshot at trimmed cursor = %d %v body=%s", w.Code, body, w.Body.String())
590			}
591			w, body = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
592			if w.Code != http.StatusOK || body["created"] != false {
593				t.Fatalf("repeat snapshot = %d %v body=%s", w.Code, body, w.Body.String())
594			}
595			// A cursor beyond the high-water mark is still a 400.
596			w, _ = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 3, "state": nil})
597			if w.Code != http.StatusBadRequest {
598				t.Fatalf("snapshot beyond boundary = %d, want 400", w.Code)
599			}
600		}
601		snapshotAtOne(h)
602	
603		// The new snapshot restores; the repeat restore is idempotent with the
604		// first cursor.
605		restore := func(h http.Handler) {
606			t.Helper()
607			w, body := postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
608				"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
609			})
610			if w.Code != http.StatusOK || body["created"] != true ||
611				int64(body["cursor"].(float64)) != 3 || int64(body["restoredFrom"].(float64)) != 1 {
612				t.Fatalf("restore = %d %v body=%s", w.Code, body, w.Body.String())
613			}
614			w, body = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
615				"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
616			})
617			if w.Code != http.StatusOK || body["created"] != false || int64(body["cursor"].(float64)) != 3 {
618				t.Fatalf("repeat restore = %d %v body=%s", w.Code, body, w.Body.String())
619			}
620		}
621		restore(h)
622		_ = s.Close()
623	
624		// After a restart the snapshot, the restore idempotency and the cursor
625		// judgment are unchanged.
626		h, s = open(t)
627		defer func() { _ = s.Close() }()
628		w, body := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
629		if w.Code != http.StatusOK || body["created"] != false {
630			t.Fatalf("snapshot after restart = %d %v body=%s", w.Code, body, w.Body.String())
631		}
632		w, body = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
633			"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
634		})
635		if w.Code != http.StatusOK || body["created"] != false || int64(body["cursor"].(float64)) != 3 {
636			t.Fatalf("restore after restart = %d %v body=%s", w.Code, body, w.Body.String())
637		}
638	}
